(()=>{"use strict";const circled=["①","②","③","④","⑤"];const ladderItems=[{badge:"원문항",name:"2027학년도 수능 공통 12번",original:true,body:["등차수열 $\\{a_n\\}$의 첫째항부터 제$n$항까지의 합을 $S_n$이라 하자.",{d:"a_3 = |a_8|, \\quad S_3 = S_8 + 15"},"일 때, $S_4$의 값은? [4점]"],choices:["66","69","72","75","78"],answer:2},{badge:"1단계",name:"숫자만 바꿈",body:["등차수열 $\\{a_n\\}$의 첫째항부터 제$n$항까지의 합을 $S_n$이라 하자.",{d:"a_2 = |a_7|, \\quad S_2 = S_7 + 20"},"일 때, $S_3$의 값은? [4점]"],choices:["60","63","66","69","72"],answer:0},{badge:"2단계",name:"표현 바꿈",body:["등차수열 $\\{a_n\\}$이 다음 조건을 만족시킨다.","$|a_9|$의 값은 $a_2$와 같고, $\\displaystyle\\sum_{k=4}^{8} a_k = -10$이다.","$\\displaystyle\\sum_{k=1}^{4} a_k$의 값은? [4점]"],choices:["40","42","44","46","48"],answer:4},{badge:"3단계",name:"푸는 핵심은 같고 겉이 다름",body:["최고차항의 계수가 $1$인 이차함수 $f(x)$가 다음 조건을 만족시킨다.",{d:"f(1) = |f(3)|, \\quad f(4) = 1"},"$f(5)$의 값은? [4점]"],choices:["4","5","6","7","8"],answer:1},{badge:"4단계",name:"한 걸음 더함",body:["공차가 정수인 등차수열 $\\{a_n\\}$이 다음 조건을 만족시킨다.",{box:["(가) $a_5 = -4$","(나) $a_3 = |a_k|$인 $3$이 아닌 자연수 $k$가 있다."]},"모든 $a_1$의 값의 합은? [4점]"],choices:["28","32","36","40","44"],answer:3}];const esc=s=>String(s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;");const rich=(line,tex)=>String(line).split(/\$([^$]+)\$/).map((part,i)=>i%2?tex(part,false):esc(part)).join("");const block=(b,tex)=>{if(typeof b==="string")return`<p>${rich(b,tex)}</p>`;if(b.d)return`<div class="tsc60-display">${tex(b.d,true)}</div>`;if(b.box)return`<div class="tsc60-box">${b.box.map(l=>`<p>${rich(l,tex)}</p>`).join("")}</div>`;return""};const question=(item,tex)=>`<div class="tsc60-q">${item.body.map(b=>block(b,tex)).join("")}<p class="tsc60-choices ${window.DSMathTypeset?.choiceRow(item.choices)||"ch3"}">${item.choices.map((c,i)=>`<span>${circled[i]} ${tex(c,false)}</span>`).join("")}</p></div>`;function ladder(tex){const rungs=ladderItems.map((item,i)=>`<li class="tsc60-rung${item.original?" tsc60-rung--original":""}" style="--rung:${i}">\n        <p class="tsc60-tag"><span class="tsc60-badge">${item.badge}</span><strong>${item.name}</strong></p>\n        ${question(item,tex)}\n        <p class="tsc60-answer"><span>정답</span> <span class="tsc60-answer-v">${circled[item.answer]} ${tex(item.choices[item.answer],false)}</span></p>\n      </li>`).join("");return`<section class="tsc60-ladder-wrap" aria-label="원문항과 네 단계 변형 결과"><ol class="tsc60-ladder">${rungs}</ol></section>`}const plate=(label,side,tex,original)=>`<figure class="tsc60-plate${original?" tsc60-plate--original":""}"><figcaption><span class="tsc60-badge">${label}</span></figcaption>${question(side,tex)}</figure>`;function pair(p,tex){return`<article class="tsc60-pair">\n        <header><p class="tsc60-subject">${p.subject} <span>${p.unit}</span></p></header>\n        <div class="tsc60-pair-body">${plate("원문항",p.original,tex,true)}<span class="tsc60-arrow" aria-hidden="true">→</span>${plate("변형 결과",p.variant,tex)}</div>\n        <p class="tsc60-cite">출처: ${p.cite}</p>\n      </article>`}function pairs(list,tex){return`<section class="tsc60-pairs" aria-labelledby="tsc60-pairs-title"><h2 id="tsc60-pairs-title">다른 문항에서도</h2><div class="tsc60-pair-list">${list.map(p=>pair(p,tex)).join("")}</div></section>`}const hero=back=>`<header class="tsc60-hero">\n        ${back||""}\n        <p class="tsc60-eyebrow">DELTASKILL 문항 변형</p>\n        <h1 id="tsc60-title">수능 한 문제를,<br>네 단계 새 문제로.</h1>\n        <p class="tsc60-lead">2027학년도 수능 수학 공통 12번을 델타스킬이 네 단계로 바꾼 결과입니다. 단계가 오를수록 원문항과 멀어집니다.</p>\n      </header>`;const smallPairs=[{subject:"수학Ⅱ",unit:"다항함수의 적분법",cite:"2027학년도 대학수학능력시험 수학 공통 9번 · 4점",original:{body:["수직선 위를 움직이는 점 P가 있다. 시각이 $t\\,(t \\ge 0)$일 때 점 P의 속도 $v(t)$는",{d:"v(t) = 3t^2 - 18t + 15"},"이다. 시각 $t = 0$부터 $t = 2$까지 점 P가 움직인 거리는? [4점]"],choices:["9","10","11","12","13"]},variant:{body:["수직선 위를 움직이는 점 P가 있다. 시각 $t\\,(t \\ge 0)$일 때 점 P의 속도 $v(t)$는",{d:"v(t) = 3(t-1)(t-a) \\quad (a > 2\\text{인 상수})"},"이다. 시각 $t = 0$부터 $t = 2$까지 점 P가 움직인 거리가 $15$일 때, $a$의 값은? [4점]"],choices:["4","5","6","7","8"]}},{subject:"확률과 통계",unit:"확률",cite:"2027학년도 대학수학능력시험 수학 확률과 통계 26번 · 3점",original:{body:["한 개의 주사위를 두 번 던져 나오는 눈의 수를 차례로 $a$, $b$라 하자. $5 \\le a \\times b \\le 28$일 확률은? [3점]"],choices:["\\dfrac{1}{4}","\\dfrac{13}{36}","\\dfrac{17}{36}","\\dfrac{7}{12}","\\dfrac{25}{36}"]},variant:{body:["한 개의 주사위를 세 번 던져 나오는 눈의 수를 차례로 $a$, $b$, $c$라 하자. $4 \\le a \\times b \\times c \\le 200$일 확률은? [3점]"],choices:["\\dfrac{103}{108}","\\dfrac{26}{27}","\\dfrac{209}{216}","\\dfrac{35}{36}","\\dfrac{53}{54}"]}}];const tex=(src,display)=>`<span class="tsc60-m"${display?' data-display=""':""} data-tex="${esc(src)}">${esc(src)}</span>`;function typeset(root){const run=()=>{if(!window.katex||!window.DSMathTypeset)return false;for(const el of root.querySelectorAll(".tsc60-m[data-tex]")){const src=el.getAttribute("data-tex");el.innerHTML=window.DSMathTypeset.html(src,{display:el.hasAttribute("data-display")});el.removeAttribute("data-tex")}return true};if(!run()){document.addEventListener("DOMContentLoaded",run,{once:true});window.addEventListener("load",run,{once:true})}}window.DSLadderV60=Object.freeze({items:ladderItems,question:question,tex:tex,typeset:typeset,circled:circled});if(typeof route!=="function"||typeof header!=="function")return;const previousRoute=route;function page(){return`<article class="tsc60" aria-labelledby="tsc60-title">\n      ${hero('<a class="tsc60-back" href="#csat"><span aria-hidden="true">←</span> 수능 공부</a>')}\n      ${ladder(tex)}\n      ${pairs(smallPairs,tex)}\n      <section class="tsc60-figures" aria-label="변형 규모">\n        <dl>\n          <div><dt>2027학년도 수능 수학<br>공통 · 확률과 통계</dt><dd>30<span>문항 모두</span></dd></div>\n          <div><dt>만든 변형 문항</dt><dd>180<span>개</span></dd></div>\n        </dl>\n        <p class="tsc60-note">2026년 11월 델타스킬 집계. 위 문항들은 그 가운데 고른 예시입니다.</p>\n      </section>\n      <footer class="tsc60-foot">\n        <details><summary>학습 기술과 특허 출원 5건 보기</summary><p>대한민국 특허 출원 · 2026년 11월 12일</p><ol><li><h3>문제를 풀 때 어떤 판단이 필요한가</h3><p>문제와 해설에서 풀이에 필요한 판단과 그 순서를 찾아 정리합니다.</p></li><li><h3>같은 판단을 다른 문제에서도 연습할 수 있는가</h3><p>문제의 조건을 바꾸어도 연습하려는 핵심 판단이 남아 있는지 확인합니다.</p></li><li><h3>어느 단계에서 막혔는가</h3><p>학생이 적은 풀이를 바탕으로 어디까지 진행했는지 살피고, 답을 알려 주지 않고 다음 판단을 안내합니다.</p></li><li><h3>어떤 설명이 다음 문제에 도움이 되었는가</h3><p>설명을 본 뒤 다른 문제에서 같은 판단을 해냈는지 살펴, 다음 설명을 고르는 데 반영합니다.</p></li><li><h3>도움 없이 스스로 풀었는가</h3><p>풀이 전에 어떤 도움을 받았는지 살펴 자력 풀이와 도움 풀이를 구분합니다. 근거가 부족하면 판정을 보류합니다.</p></li></ol><a href="/features/variation.html">실제 문항의 변형 과정 보기 →</a></details>\n        <p>특허출원 · <span>문항 분석 10-2026-0226038</span> · <span>문항 변형 10-2026-0226050</span></p>\n        <p>수능 원문항 출처: 한국교육과정평가원 2027학년도 대학수학능력시험 수학 영역 문제지</p>\n        <a class="tsc60-cta" href="#csat">수능 공부로 가기 <span aria-hidden="true">→</span></a>\n      </footer>\n    </article>${typeof compactFooter==="function"?compactFooter():""}`}function navigate(){if(location.hash!=="#technology")return previousRoute.apply(this,arguments);const content=document.getElementById("content");if(!content)return;if(typeof cinemaTimer!=="undefined")clearTimeout(cinemaTimer);if(typeof clock!=="undefined")clearInterval(clock);if(typeof diagnosticClock!=="undefined")clearInterval(diagnosticClock);header("technology");document.title="델타스킬 기술 · DELTASKILL";content.innerHTML=page();typeset(content);window.scrollTo(0,0);content.focus({preventScroll:true})}window.removeEventListener("hashchange",previousRoute);route=navigate;window.addEventListener("hashchange",navigate);if(location.hash==="#technology")navigate()})();
